  uint32_t vertex_count;
  uint32_t tag_point_count;
  uint32_t material_count;
  uint32_t frame_count;
  uint32_t sub_model_count;
  uint32_t lod_count;
  EeGeBytes name;
  /// The centre's values read (x, y, z; a prefix).
